package com.example

import com.example.ExamQuestionHelper.QSpec
import com.example.ExamQuestionHelper.buildMcq
import com.example.ExamQuestionHelper.slotOf
import com.example.ExamQuestionHelper.variantOf

/**
 * Grade 11 Mathematics Question Bank for Live Exam Hall.
 * 60 distinct Grade 11 syllabus problem generators per Term × 30 injective parameter sets = 1,800 unique problems per Term (5,400 total).
 */
object MathGrade11QuestionBank {

  fun getQuestion(term: Int, paperIdx: Int, qNum: Int): MockExamQuestion {
    val cleanTerm = if (term in 1..3) term else 1
    val slot = slotOf(paperIdx, qNum) // 0..59
    val v = variantOf(paperIdx)        // 0..29
    val spec = when (cleanTerm) {
      1 -> term1Spec(slot, v)
      2 -> term2Spec(slot, v)
      else -> term3Spec(slot, v)
    }
    return buildMcq(
      id = qNum,
      topic = spec.topic,
      questionText = spec.questionText,
      correct = spec.correct,
      distractors = spec.distractors,
      explanation = spec.explanation,
      seed = (cleanTerm + 3) * 10000 + paperIdx * 100 + qNum
    )
  }

  // --------------------------------------------------------------------------
  // GRADE 11 — TERM 1: Real Numbers/Surds, Quadratics, Graphs, Log II, Ratio, Solids
  // --------------------------------------------------------------------------
  private fun term1Spec(slot: Int, v: Int): QSpec {
    val a = 2 + v
    return when (slot) {
      0 -> {
        val p = 2 + v; val q = 3 + v
        QSpec("වර්ගජ සමීකරණ", "x² - ${p + q}x + ${p * q} = 0 වර්ගජ සමීකරණයේ මූල මොනවාද?", "x = $p හෝ x = $q", listOf("x = -$p හෝ x = -$q", "x = $p හෝ x = -$q", "x = 1 හෝ x = ${p * q}"), "(x - $p)(x - $q) = 0 => x = $p හෝ $q.")
      }
      1 -> QSpec("වර්ගජ සමීකරණ", "x² + ${a + 2}x = 0 වර්ගජ සමීකරණයේ ශුන්‍ය නොවන මූලය කුමක්ද?", "-${a + 2}", listOf("${a + 2}", "0", "-${a}"), "x(x + ${a + 2}) = 0 => x = -${a + 2}.")
      2 -> QSpec("වර්ගජ සමීකරණ", "x² - ${a * a} = 0 සමීකරණයේ විසඳුම් යුගලය කුමක්ද?", "x = $a සහ x = -$a", listOf("x = $a පමණි", "x = ${a * a} සහ x = -${a * a}", "x = 0"), "x² = ${a * a} => x = ±$a.")
      3 -> QSpec("වර්ගජ සමීකරණ", "x² + ${2 * a}x + ${a * a} = 0 සමීකරණයේ සමපාත මූලය කුමක්ද?", "x = -$a", listOf("x = $a", "x = ${2 * a}", "x = 0"), "(x + $a)² = 0 => x = -$a.")
      4 -> QSpec("වර්ගජ සමීකරණ", "x² + ${2 * a}x = ${2 * a + 1} සමීකරණය පූර්ණ වර්ග කිරීමේදී දෙපසටම එකතු කළ යුතු නියතය කුමක්ද?", "${a * a}", listOf("${2 * a}", "$a", "${4 * a * a}"), "(b/2)² = ($a)² = ${a * a}.")
      5 -> QSpec("වර්ගජ සමීකරණ", "(x - $a)² - 9 = 0 සමීකරණයේ ධන මූලය කුමක්ද?", "${a + 3}", listOf("${a - 3}", "${a + 9}", "${3 * a}"), "x - $a = ±3 => ධන මූලය = ${a + 3}.")
      6 -> QSpec("වර්ගජ සමීකරණ", "ax² + ${a * 4}x + ${a} = 0 වර්ගජ සමීකරණයේ විවේචකයේ (Δ = b² - 4ac) අගය කොපමණද?", "${12 * a * a}", listOf("${16 * a * a}", "${4 * a * a}", "${20 * a * a}"), "Δ = (${4 * a})² - 4($a)($a) = ${16 * a * a} - ${4 * a * a} = ${12 * a * a}.")
      7 -> QSpec("වර්ගජ ශ්‍රිත ප්‍රස්ථාර", "y = (x - $a)² + ${a + 3} වර්ගජ ප්‍රස්ථාරයේ හැරවුම් ලක්ෂ්‍යයේ (ශීර්ෂයේ) ඛණ්ඩාංක මොනවාද?", "($a, ${a + 3})", listOf("(-$a, ${a + 3})", "($a, -${a + 3})", "(0, ${a + 3})"), "ශීර්ෂය (h, k) = ($a, ${a + 3}).")
      8 -> QSpec("වර්ගජ ශ්‍රිත ප්‍රස්ථාර", "y = (x + $a)² - ${2 * a} ප්‍රස්ථාරයේ සමමිතික අක්ෂයේ සමීකරණය කුමක්ද?", "x = -$a", listOf("x = $a", "y = -${2 * a}", "y = $a"), "x + $a = 0 => x = -$a.")
      9 -> QSpec("වර්ගජ ශ්‍රිත ප්‍රස්ථාර", "y = -(x - 3)² + ${a + 5} ශ්‍රිතයේ උපරිම අගය කොපමණද?", "${a + 5}", listOf("3", "-${a + 5}", "-3"), "ශීර්ෂයේ y-ඛණ්ඩාංකය වන ${a + 5} උපරිම අගයයි.")
      10 -> QSpec("වර්ගජ ශ්‍රිත ප්‍රස්ථාර", "y = (x - 4)² + ${a - 1} ප්‍රස්ථාරයේ අවම අගය කීයද?", "${a - 1}", listOf("4", "-4", "${a + 3}"), "අවම අගය ${a - 1}.")
      11 -> QSpec("වර්ගජ ශ්‍රිත ප්‍රස්ථාර", "y = x² - ${a * a} වක්‍රය x-අක්ෂය ඡේදනය කරන ලක්ෂ්‍ය මොනවාද?", "($a, 0) සහ (-$a, 0)", listOf("(0, -$a)", "(${a * a}, 0) සහ (-${a * a}, 0)", "(0, $a)"), "y = 0 විට x² = ${a * a} => x = ±$a.")
      12 -> QSpec("කරණි (Surds)", "√(${a * a * 2}) සරලම කරණිය ලෙස ලියූ විට ලැබෙන්නේ කුමක්ද?", "${a}√2", listOf("2√$a", "${2 * a}√2", "${a * a}√2"), "√(${a * a} × 2) = ${a}√2.")
      13 -> QSpec("කරණි (Surds)", "${a}√3 + ${a + 2}√3 සුළු කළ විට ලැබෙන පිළිතුර කුමක්ද?", "${2 * a + 2}√3", listOf("${2 * a + 2}√6", "${a * (a + 2)}√3", "${2 * a}√3"), "සමාන කරණි සංගුණක එකතු වේ: (${a} + ${a + 2})√3 = ${2 * a + 2}√3.")
      14 -> QSpec("කරණි (Surds)", "√$a × √${4 * a} ගුණිතයේ නිවැරදි අගය කොපමණද?", "${2 * a}", listOf("${4 * a}", "${a}√2", "$a"), "√(${4 * a * a}) = ${2 * a}.")
      15 -> QSpec("කරණි (Surds)", "$a / √3 හරය පරිමේය (Rationalize) කළ විට ලැබෙන්නේ කුමක්ද?", "${a}√3 / 3", listOf("${a * 3} / √3", "√3 / $a", "$a / 3"), "ලවය හා හරය √3 න් ගුණ කළ විට ${a}√3 / 3.")
      16 -> QSpec("ලඝුගණක II", "log₁₀(x) = ${a % 5 + 1}.${v + 10} නම් (ලඝුගණක පූර්ණාංශය = ${a} විට), අදාළ සංඛ්‍යාවේ දශම තිතට පෙර ඇති ඉලක්කම් ගණන කීයද?", "${a + 1}", listOf("$a", "${a - 1}", "${a + 2}"), "පූර්ණාංශය $a නම් ඉලක්කම් ගණන = $a + 1 = ${a + 1}.")
      17 -> QSpec("ලඝුගණක II", "log(${2 * a}) - log(2) සරල කළ විට ලැබෙන ප්‍රකාශනය කුමක්ද?", "log($a)", listOf("log(${2 * a - 2})", "log(${4 * a})", "log(2)"), "log(${2 * a}/2) = log($a).")
      18 -> QSpec("ලඝුගණක II", "2 log₁₀(x) = 2 log₁₀($a) + log₁₀(1) නම් x හි ධන අගය කුමක්ද?", "$a", listOf("${a * a}", "1", "${2 * a}"), "log(x²) = log($a²) => x = $a.")
      19 -> QSpec("දර්ශක හා ලඝුගණක", "8^${a} යන්න 2 හි බලයක් ලෙස ලියූ විට කුමක්ද?", "2^${3 * a}", listOf("2^${a + 3}", "2^${2 * a}", "4^${a}"), "(2³)^$a = 2^${3 * a}.")
      20 -> QSpec("අනුපාත", "මිනිසුන් $a දෙනෙකු දින 10 කින් නිම කරන වැඩක් දින 5 කින් නිම කිරීමට අවශ්‍ය මිනිසුන් ගණන කීයද?", "${2 * a}", listOf("${a / 2}", "${a + 5}", "${3 * a}"), "මිනිස් දින ${10 * a} / 5 = ${2 * a}.")
      21 -> QSpec("අනුපාත", "a : b = 3 : 4 සහ b : c = 4 : $a නම්, a : c අනුපාතය කුමක්ද?", "3 : $a", listOf("4 : $a", "3 : 4", "$a : 3"), "b පොදු බැවින් a : c = 3 : $a.")
      22 -> QSpec("සමානුපාත", "සිතියම් පරිමාණය 1 : 25 000 කි. සිතියමේ ${2 + v} cm ක දුරකින් පෙන්වන සැබෑ බිම් දුර මීටර කීයද?", "${(2 + v) * 250} m", listOf("${(2 + v) * 25} m", "${(2 + v) * 2500} m", "${(2 + v) * 500} m"), "${2 + v} × 25000 cm = ${(2 + v) * 250} m.")
      23 -> QSpec("සිලින්ඩර හා කේතු", "පාදමේ අරය 7 cm සහ ඇල උස $a cm වූ ඍජු වෘත්ත කේතුවක වක්‍ර පෘෂ්ඨ වර්ගඵලය (π = 22/7) කීයද?", "${22 * a} cm²", listOf("${44 * a} cm²", "${154 * a} cm²", "${11 * a} cm²"), "πrl = (22/7) × 7 × $a = ${22 * a} cm².")
      24 -> QSpec("සිලින්ඩර හා කේතු", "පාදමේ අරය 7 cm සහ ලම්භ උස ${3 * a} cm වූ කේතුවක පරිමාව (π = 22/7) කොපමණද?", "${154 * a} cm³", listOf("${462 * a} cm³", "${77 * a} cm³", "${308 * a} cm³"), "(1/3)πr²h = (1/3) × 154 × ${3 * a} = ${154 * a} cm³.")
      25 -> QSpec("පිරමීඩ", "පාදමේ වර්ගඵලය ${6 * a} cm² සහ ලම්භ උස 5 cm වූ ඍජු පිරමීඩයක පරිමාව කීයද?", "${10 * a} cm³", listOf("${30 * a} cm³", "${15 * a} cm³", "${6 * a} cm³"), "(1/3) × පාදම් වර්ගඵලය × උස = (1/3) × ${6 * a} × 5 = ${10 * a} cm³.")
      26 -> QSpec("ගෝල", "අරය 7 cm ක් හා වෙළඳ නාම පරීක්ෂණ මගින් මුළු ගණන ${a} ක් වූ කුඩා ගෝලයක නොව, අරය ${7 * (v + 1)} cm වූ ගෝලයක වර්ගඵල සාධකය 4πr² අනුව පෘෂ්ඨ වර්ගඵලය කීයද?", "${616 * (v + 1) * (v + 1)} cm²", listOf("${308 * (v + 1) * (v + 1)} cm²", "${154 * (v + 1) * (v + 1)} cm²", "${1232 * (v + 1)} cm²"), "4 × (22/7) × (${7 * (v + 1)})² = ${616 * (v + 1) * (v + 1)} cm².")
      27 -> QSpec("ගෝල", "අරය ${3 * a} cm වූ ඝන ගෝලයක පෘෂ්ඨ වර්ගඵලය π ඇසුරින් දක්වන්න.", "${36 * a * a}π cm²", listOf("${9 * a * a}π cm²", "${12 * a * a}π cm²", "${18 * a * a}π cm²"), "4πr² = 4π(${3 * a})² = ${36 * a * a}π cm².")
      28 -> QSpec("අර්ධ ගෝල", "අරය 7 cm වූ ඝන අර්ධ ගෝලයක (මුහුණත + වක්‍ර පෘෂ්ඨය) මුළු පෘෂ්ඨ වර්ගඵලය r = ${7 * (v + 1)} cm විට (π = 22/7) කොපමණද?", "${462 * (v + 1) * (v + 1)} cm²", listOf("${308 * (v + 1) * (v + 1)} cm²", "${154 * (v + 1) * (v + 1)} cm²", "${616 * (v + 1) * (v + 1)} cm²"), "3πr² = 3 × 154 × ${(v + 1) * (v + 1)} = ${462 * (v + 1) * (v + 1)} cm².")
      29 -> QSpec("වැල් පොලිය", "රු. ${10000 + v * 2000} ක් වාර්ෂික 10% වැල් පොලියට වසර 2 ක් තැන්පත් කළ විට දෙවන වසර අවසානයේ ලැබෙන මුළු මුදල කීයද?", "රු. ${((10000 + v * 2000) * 121) / 100}", listOf("රු. ${((10000 + v * 2000) * 120) / 100}", "රු. ${((10000 + v * 2000) * 110) / 100}", "රු. ${((10000 + v * 2000) * 21) / 100}"), "A = P(1.1)² = P × 1.21.")
      else -> term1Part2Spec(slot, v, a)
    }
  }

  private fun term1Part2Spec(slot: Int, v: Int, a: Int): QSpec {
    return when (slot) {
