        QSpec("සමමිතිකතාව", "පාද $m cm වූ සමපාද ත්‍රිකෝණයකට ඇති සමමිතික අක්ෂ ගණන කොපමණද?", "3", listOf("1", "2", "6"), "සමපාද ත්‍රිකෝණයකට සමමිතික අක්ෂ 3 ක් ඇත.")
      }
      28 -> {
        val m = k + (slot / 30) * 31
        QSpec("වැඩ සහ කාලය", "නලයකින් මිනිත්තුවකට ජලය ලීටර $m ක් පිරේ නම්, ලීටර ${12 * m} ක ටැංකියක් පිරවීමට කොපමණ මිනිත්තු ගණනක් ගතවේද?", "මිනිත්තු 12", listOf("මිනිත්තු $m", "මිනිත්තු 6", "මිනිත්තු 24"), "${12 * m} / $m = 12 min.")
      }
      else -> {
        val m = k + (slot / 30) * 31
        QSpec("පෘෂ්ඨ වර්ගඵලය", "උස ${2 * m} cm සහ අරය 7 cm වූ සිලින්ඩරයක වක්‍ර පෘෂ්ඨ වර්ගඵලය (π = 22/7) කීයද?", "${88 * m} cm²", listOf("${44 * m} cm²", "${308 * m} cm²", "${154 * m} cm²"), "2πrh = 2 × (22/7) × 7 × ${2 * m} = ${88 * m} cm².")
      }
    }
  }

  // --------------------------------------------------------------------------
  // GRADE 11 — TERM 3: O/L Full Final Revision (60 Distinct Problem Generators)
  // --------------------------------------------------------------------------
  private fun term3Spec(slot: Int, v: Int): QSpec {
    val base = 10 + v
    val group = slot / 20 // 0, 1, 2
    val sub = slot % 20
    val m = base + group * 35
    return when (sub) {
      0 -> QSpec("මූලික සංඛ්‍යා හා ප්‍රතිශත", "රු. ${m * 20} ක වටිනාකමකින් යුත් භාණ්ඩයකට 15% ක තීරු බද්දක් එකතු කළ විට නව වටිනාකම කීයද?", "රු. ${m * 23}", listOf("රු. ${m * 3}", "රු. ${m * 17}", "රු. ${m * 25}"), "20 + 15% = 23 කොටස් => රු. ${m * 23}.")
      1 -> QSpec("වර්ගජ සමීකරණ", "x² + ${2 * m}x + ${m * m - 1} = 0 සමීකරණයේ ඍණ මූල දෙක කුමක්ද?", "-${m - 1} සහ -${m + 1}", listOf("${m - 1} සහ ${m + 1}", "-$m සහ 1", "$m සහ -$m"), "(x + ${m - 1})(x + ${m + 1}) = 0.")
      2 -> QSpec("ප්‍රස්ථාර හා ශ්‍රිත", "y = (x - $m)² + 7 වක්‍රයේ හැරවුම් ලක්ෂ්‍යය කුමක්ද?", "($m, 7)", listOf("(-$m, 7)", "(7, $m)", "($m, -7)"), "ශීර්ෂය ($m, 7).")
      3 -> QSpec("ලඝුගණක", "log₁₀(100^$m) හි සංඛ්‍යාත්මක අගය කොපමණද?", "${2 * m}", listOf("$m", "${10 * m}", "${2 + m}"), "100^$m = 10^${2 * m} => ලඝුගණකය ${2 * m}.")
      4 -> QSpec("ශ්‍රේඪි", "පළමු පදය $m සහ පොදු අන්තරය 5 වන සමාන්තර ශ්‍රේඪියේ 7 වන පදය කීයද?", "${m + 30}", listOf("${m + 35}", "${m + 25}", "${5 * m}"), "T₇ = $m + 6(5) = ${m + 30}.")
      5 -> QSpec("ශ්‍රේඪි", "පළමු පදය 2 සහ පොදු අනුපාතය 2 වන ගුණෝත්තර ශ්‍රේඪියක, ආරම්භක පදය $m ලෙස වෙනස් කළහොත් 3 වන පදය කීයද?", "${4 * m}", listOf("${2 * m}", "${8 * m}", "${6 * m}"), "T₃ = $m × 2² = ${4 * m}.")
      6 -> {
        val periAng = 15 + group * 20 + (v % 20) + (v / 20) * 60
        // Unique across all 90 combinations: group*30 + v gives 0..89 -> +10 = 10..99 ( Wait: central angle 2*ang up to 178° -> 1..89!)
        val uIdx = group * 30 + v // 0..89
        val pAng = 1 + uIdx       // 1°..89° (Wait: uIdx=89 -> 90°, valid acute/right inscribed angle!)
        QSpec("ජ්‍යාමිතිය - වෘත්ත", "වෘත්තයක චාපයක් කේන්ද්‍රයේ ආපාතනය කරන කෝණය ${2 * pAng}° නම්, ඉතිරි පරිධියේ ආපාතනය කරන කෝණය කීයද?", "$pAng°", listOf("${2 * pAng}°", "${90 - (pAng % 45)}°", "${180 - pAng}°"), "පරිධි කෝණය කේන්ද්‍ර කෝණයෙන් අඩකි: ${2 * pAng}° / 2 = $pAng°.")
      }
      7 -> {
        val cAng = 40 + group * 35 + v // 40°..139°, all 90 distinct!
        QSpec("චක්‍රීය චතුරස්‍ර", "චක්‍රීය චතුරස්‍රයක එක් අභ්‍යන්තර කෝණයක් $cAng° නම්, එහි සම්මුඛ කෝණයේ විශාලත්වය කීයද?", "${180 - cAng}°", listOf("$cAng°", "${360 - cAng}°", "${90}°"), "සම්මුඛ කෝණ එකතුව 180° බැවින් 180° - $cAng° = ${180 - cAng}°.")
      }
      8 -> QSpec("පයිතගරස් ප්‍රමේයය", "සෘජුකෝණී ත්‍රිකෝණයක කර්ණය ${5 * m} cm සහ එක් පාදයක් ${4 * m} cm නම් ඉතිරි පාදය කීයද?", "${3 * m} cm", listOf("${2 * m} cm", "${6 * m} cm", "${m} cm"), "3:4:5 ත්‍රිකය අනුව ${3 * m} cm.")
      9 -> QSpec("ත්‍රිකෝණමිතිය", "sin θ = $m / ${m + 4} නම් cosec θ හි අගය කුමක්ද?", "${m + 4} / $m", listOf("$m / ${m + 4}", "4 / $m", "$m / 4"), "cosec θ = 1 / sin θ = ${m + 4} / $m.")
      10 -> QSpec("පරිමාව හා ක්ෂේත්‍රඵලය", "හරස්කඩ වර්ගඵලය ${m} cm² සහ උස 12 cm වූ ප්‍රිස්මයක පරිමාව කීයද?", "${12 * m} cm³", listOf("${6 * m} cm³", "${m + 12} cm³", "${24 * m} cm³"), "$m × 12 = ${12 * m} cm³.")
      11 -> QSpec("සිලින්ඩර", "අරය 7 cm සහ උස $m cm වූ සිලින්ඩරයක පරිමාව (π = 22/7) කීයද?", "${154 * m} cm³", listOf("${44 * m} cm³", "${77 * m} cm³", "${308 * m} cm³"), "154 × $m = ${154 * m} cm³.")
      12 -> QSpec("කුලක", "n(A) = ${m + 12}, n(B) = ${m + 8} සහ n(A ∩ B) = $m නම් n(A ∪ B) කීයද?", "${m + 20}", listOf("${2 * m + 20}", "${m + 12}", "20"), "(${m + 12}) + (${m + 8}) - $m = ${m + 20}.")
      13 -> QSpec("සම්භාවිතාව", "කළු බෝල $m ක් හා සුදු බෝල 5 ක් ඇති මල්ලකින් සුදු බෝලයක් ගැනීමේ සම්භාවිතාව කීයද?", "5 / ${m + 5}", listOf("$m / ${m + 5}", "5 / $m", "1 / ${m + 5}"), "මුළු බෝල ${m + 5}; සුදු බෝල 5.")
      14 -> QSpec("සංඛ්‍යානය", "$m, ${m + 1}, ${m + 2}, ${m + 3}, ${m + 4} සංඛ්‍යා 5 හි මධ්‍යන්‍යය කීයද?", "${m + 2}", listOf("${m + 1}", "${m + 3}", "$m"), "එකතුව ${5 * (m + 2)} / 5 = ${m + 2}.")
      15 -> QSpec("ඛණ්ඩාංක ජ්‍යාමිතිය", "(0, $m) සහ (4, ${m + 8}) අතර ඇති රේඛාවේ අනුක්‍රමණය කීයද?", "2", listOf("$m", "4", "8"), "(${m + 8} - $m) / (4 - 0) = 2.")
      16 -> QSpec("න්‍යාස", "[[$m, 3], [1, 2]] + [[2, 1], [3, $m]] න්‍යාසයේ ප්‍රධාන විකර්ණ අවයව දෙකෙහි එකතුව කීයද?", "${2 * m + 4}", listOf("${m + 2}", "${2 * m}", "10"), "(${m + 2}) + (${2 + m}) = ${2 * m + 4}.")
      17 -> QSpec("වීජීය භාග", "((x² - 4) / (x + 2)) + $m සුළු කළ විට (x ≠ -2) ලැබෙන්නේ කුමක්ද?", "x + ${m - 2}", listOf("x + ${m + 2}", "x - $m", "x + 2"), "(x - 2) + $m = x + ${m - 2}.")
      18 -> QSpec("අනුපාත", "රු. ${m * 500} ක් 1 : 4 අනුපාතයට බෙදූ විට කුඩා කොටස කීයද?", "රු. ${m * 100}", listOf("රු. ${m * 400}", "රු. ${m * 200}", "රු. ${m * 250}"), "1/5 × ${m * 500} = රු. ${m * 100}.")
      else -> QSpec("කොටස් වෙළඳපොල", "කොටසකට රු. 5 බැගින් කොටස් ${m * 10} ක් සඳහා ලැබෙන වාර්ෂික ලාභාංශය කීයද?", "රු. ${m * 50}", listOf("රු. ${m * 10}", "රු. ${m * 25}", "රු. ${m * 100}"), "5 × ${m * 10} = රු. ${m * 50}.")
    }
  }
